// 移动端视口
// <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">

// 1px边框解决方案
.border-1px {
  position: relative;
}
.border-1px::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: 0;
  width: 100%;
  height: 1px;
  background: #000;
  transform: scaleY(0.5);
  transform-origin: 0 0;
}

/* 或使用border-image */
.border-1px {
  border-bottom: 1px solid transparent;
  border-image: linear-gradient(to bottom, transparent 50%, #000 50%) 0 0 1 0;
}

// 触摸事件处理
function useSwipe(callback) {
  const startRef = useRef(null);

  const onTouchStart = (e) => {
    startRef.current = {
      x: e.touches[0].clientX,
      y: e.touches[0].clientY,
      time: Date.now()
    };
  };

  const onTouchEnd = (e) => {
    if (!startRef.current) return;
    const deltaX = e.changedTouches[0].clientX - startRef.current.x;
    const deltaY = e.changedTouches[0].clientY - startRef.current.y;
    const deltaTime = Date.now() - startRef.current.time;

    if (Math.abs(deltaX) > Math.abs(deltaY) && Math.abs(deltaX) > 50 && deltaTime < 300) {
      callback(deltaX > 0 ? 'right' : 'left');
    }
    startRef.current = null;
  };

  return { onTouchStart, onTouchEnd };
}

// 无限滚动
function useInfiniteScroll(callback) {
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
          callback();
        }
      },
      { threshold: 0.1 }
    );

    const sentinel = document.getElementById('sentinel');
    if (sentinel) observer.observe(sentinel);
    return () => observer.disconnect();
  }, [callback]);
}

// 虚拟列表（react-virtuoso）
import { Virtuoso } from 'react-virtuoso';

function InfiniteList() {
  const [items, setItems] = useState(initialItems);

  const loadMore = () => {
    fetchItems(nextPage).then(newItems => {
      setItems(prev => [...prev, ...newItems]);
    });
  };

  return (
    <Virtuoso
      useWindowScroll
      totalCount={items.length}
      endReached={loadMore}
      itemContent={(index) => <Item data={items[index]} />}
    />
  );
}

// 安全区域适配
// iOS刘海屏和底部安全区域
.safe-area {
  padding-top: env(safe-area-inset-top);
  padding-bottom: env(safe-area-inset-bottom);
  padding-left: env(safe-area-inset-left);
  padding-right: env(safe-area-inset-right);
}

// 禁止双指缩放
// <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">

// 禁止长按菜单
* {
  -webkit-touch-callout: none;
  -webkit-user-select: none;
}
